function schedule(tasks,gates,buffered){
const nodes=[...tasks.map(t=>({...t,duration:(t.days+(buffered?t.contingency:0))/0.7})),...gates.map(g=>({...g,duration:g.lag}))];
const by=Object.fromEntries(nodes.map(n=>[n.id,n])),memo={},visiting=new Set();
function rank(id){if(memo[id]!=null)return memo[id];if(visiting.has(id))throw Error("cycle at "+id);visiting.add(id);const next=nodes.filter(n=>n.deps.includes(id));const v=by[id].duration+Math.max(0,...next.map(n=>rank(n.id)));visiting.delete(id);memo[id]=v;return v;}
nodes.forEach(n=>rank(n.id));
const done={},lanes={},pending=new Set(nodes.map(n=>n.id));
while(pending.size){
 const ready=[...pending].map(id=>by[id]).filter(n=>n.deps.every(d=>done[d]));
 if(!ready.length)throw Error("cycle: "+[...pending]);
 const opts=ready.map(n=>{const dependencyStart=Math.max(0,...n.deps.map(d=>done[d].finish));const eligible=[...(n.eligible||[null])];const lane=eligible.sort((a,b)=>(lanes[a]?.finish||0)-(lanes[b]?.finish||0)||String(a).localeCompare(String(b)))[0];return {n,lane,dependencyStart,start:Math.max(dependencyStart,lanes[lane]?.finish||0)}});
 opts.sort((a,b)=>a.start-b.start || memo[b.n.id]-memo[a.n.id] || a.n.id.localeCompare(b.n.id));
 const {n,lane,start,dependencyStart}=opts[0],prev=lane?lanes[lane]?.id:null;
 done[n.id]={...n,lane,start,finish:start+n.duration,dependencyStart,resourcePrev:prev||null};
 if(lane)lanes[lane]={id:n.id,finish:done[n.id].finish};pending.delete(n.id);
}
return done;
}
